------------------
---- MONITORS ----
------------------

-- See https://wiki.hypr.land/Configuring/Basics/Monitors/
-- Bigger monitor (LG 1920x1080) is primary, Samsung 1366x768 to its right
hl.monitor({
    output   = "HDMI-A-2",
    mode     = "preferred",
    position = "0x0",
    scale    = "auto",
})
hl.monitor({
    output   = "DVI-D-2",
    mode     = "preferred",
    position = "1920x0",
    scale    = "auto",
})

-- Default workspaces: primary LG first, regardless of connect order
hl.workspace_rule({ workspace = "1", monitor = "HDMI-A-2", default = true })
hl.workspace_rule({ workspace = "2", monitor = "DVI-D-2", default = true })


