---------------------
---- KEYBINDINGS ----
---------------------

local mainMod = "SUPER" -- Sets "Windows" key as main modifier

-- Omarchy-style: Super+Return opens terminal; Super+Q closes window;
-- Super+C is universal copy (Ctrl+C / Ctrl+Insert in terminals);
-- Super+V is universal paste (Shift+Insert).
hl.bind(mainMod .. " + Return", hl.dsp.exec_cmd(terminal))
hl.bind(mainMod .. " + W", hl.dsp.window.close())

local function send_shortcut_once(mods, key)
  return function()
    hl.dispatch(hl.dsp.send_key_state({ mods = mods, key = key, state = "down" }))
    hl.timer(function()
      hl.dispatch(hl.dsp.send_key_state({ mods = mods, key = key, state = "up" }))
    end, { timeout = 50, type = "oneshot" })
  end
end

local function active_window_is_terminal()
  local window = hl.get_active_window()
  if not window then
    return false
  end
  local class = (window.class or window.initial_class or ""):lower()
  return class:find("ghostty", 1, true)
    or class:find("kitty", 1, true)
    or class:find("alacritty", 1, true)
    or class:find("foot", 1, true)
    or class:find("com.mitchellh.ghostty", 1, true)
end

hl.bind(mainMod .. " + C", function()
  if active_window_is_terminal() then
    send_shortcut_once("CTRL", "Insert")()
  else
    send_shortcut_once("CTRL", "C")()
  end
end)

hl.bind(mainMod .. " + V", send_shortcut_once("SHIFT", "Insert"))

hl.bind(mainMod .. " + M", hl.dsp.exec_cmd("command -v hyprshutdown >/dev/null 2>&1 && hyprshutdown || hyprctl dispatch 'hl.dsp.exit()'"))
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd(fileManager))
hl.bind(mainMod .. " + T", hl.dsp.window.float({ action = "toggle" }))   -- Omarchy: toggle floating/tiling
hl.bind(mainMod .. " + R", hl.dsp.exec_cmd(menu))
hl.bind(mainMod .. " + P", hl.dsp.window.pseudo())
hl.bind(mainMod .. " + J", hl.dsp.layout("togglesplit"))    -- dwindle only

-- Omarchy-style window management
hl.bind(mainMod .. " + F",         hl.dsp.window.fullscreen({ mode = "fullscreen" }))                                  -- Full screen
hl.bind(mainMod .. " + CTRL + F",  hl.dsp.window.fullscreen_state({ internal = 0, client = 2 }))                        -- Tiled full screen
hl.bind(mainMod .. " + ALT + F",   hl.dsp.window.fullscreen({ mode = "maximized" }))                                    -- Full width
hl.bind(mainMod .. " + O", function() -- Pop window out (float & pin)
  hl.dispatch(hl.dsp.window.float({ action = "toggle" }))
  hl.dispatch(hl.dsp.window.pin({ action = "toggle" }))
end)
hl.bind(mainMod .. " + L", function() -- Toggle dwindle/scrolling layout
  local current = hl.get_config("general.layout") or "dwindle"
  local target  = current == "dwindle" and "scrolling" or "dwindle"
  hl.config({ general = { layout = target } })
end)

-- Scrolling layout controls, https://wiki.hypr.land/Configuring/Layouts/Scrolling-Layout/
hl.bind(mainMod .. " + period",          hl.dsp.layout("move +col"))       -- scroll right one column
hl.bind(mainMod .. " + semicolon",       hl.dsp.layout("swapcol r"))       -- swap column right
hl.bind(mainMod .. " + SHIFT + period",  hl.dsp.layout("colresize +conf")) -- cycle column width forward
hl.bind(mainMod .. " + SHIFT + comma",   hl.dsp.layout("colresize -conf")) -- cycle column width backward

-- Omarchy-style tooling shortcuts
hl.bind(mainMod .. " + ALT + Return", hl.dsp.exec_cmd(terminal .. " -e tmux"))
hl.bind(mainMod .. " + SHIFT + B",    hl.dsp.exec_cmd(browser))
hl.bind(mainMod .. " + SHIFT + D",    hl.dsp.exec_cmd(terminal .. " -e lazydocker"))
hl.bind(mainMod .. " + SHIFT + N",    hl.dsp.exec_cmd(terminal .. " -e nvim"))

-- Omarchy-style clipboard: Super+Ctrl+V opens clipboard history (Noctalia panel)
hl.bind(mainMod .. " + CTRL + V", hl.dsp.exec_cmd("noctalia msg panel-toggle clipboard"))

-- Super+Print: color picker
hl.bind(mainMod .. " + Print", hl.dsp.exec_cmd("pkill hyprpicker || hyprpicker -a"))

-- Move focus with mainMod + arrow keys
hl.bind(mainMod .. " + left",  hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + up",    hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + down",  hl.dsp.focus({ direction = "down" }))

-- Switch workspaces with mainMod + [0-9]
-- Move active window to a workspace with mainMod + SHIFT + [0-9]
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    hl.bind(mainMod .. " + " .. key,             hl.dsp.focus({ workspace = i}))
    hl.bind(mainMod .. " + SHIFT + " .. key,     hl.dsp.window.move({ workspace = i }))
end

-- Scroll through existing workspaces with mainMod + scroll
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-----------------------------
---- NOCTALIA (IPC binds) ----
-----------------------------

-- See https://docs.noctalia.dev/noctalia/compositor-settings/hyprland/
local noctaliaIpc = "noctalia msg "
hl.bind(mainMod .. " + Space",  hl.dsp.exec_cmd(noctaliaIpc .. "panel-toggle launcher"))
hl.bind(mainMod .. " + CTRL + O", hl.dsp.exec_cmd(noctaliaIpc .. "panel-toggle control-center"))
-- Super+comma: noctalia settings, or swapcol when in scrolling layout
hl.bind(mainMod .. " + comma", function()
  local current = hl.get_config("general.layout") or "dwindle"
  if current == "scrolling" then
    hl.dispatch(hl.dsp.layout("swapcol l"))
  else
    hl.dispatch(hl.dsp.exec_cmd(noctaliaIpc .. "settings-toggle"))
  end
end)
hl.bind("ALT + Tab",           hl.dsp.exec_cmd(noctaliaIpc .. "window-switcher"))

hl.window_rule({
    name  = "noctalia-settings",
    match = { class = "dev.noctalia.Noctalia" },

    float = true,
    size  = { 1080, 920 },
})

local noctaliaBlurRule = hl.layer_rule({
    name  = "noctalia-blur",
    match = { namespace = "^noctalia-(bar-.+|notification|dock|panel|attached-panel|osd|window-switcher)$" },

    no_anim     = true,
    ignore_alpha = 0.5,
    blur        = true,
    blur_popups = true,
})


